static const float TRS32_b2[11] = { -0.88962191f, -0.64231116f, -0.27945420f,
                                    -0.70160180f, -0.18392405f, -0.56530648f,
                                    -0.60145503f, -1.15773451f, -1.10915279f,
                                    0.42093796f,  0.24248473f };

static float TRS32_relu(float x)
{
    return x > 0.0f ? x : 0.0f;
}

static float TRS32_sigmoid(float x)
{
    if (x > 15.0f)
        return 1.0f;
    if (x < -15.0f)
        return 0.0f;
    return 1.0f / (1.0f + expf(-x));
}

int TRS_score_num32_operations_with_logits(
        const TRS_NumericFeatures* f,
        float scores_out[TRS_SCORE_NUM32_N_OPERATIONS],
        float logits_out[TRS_SCORE_NUM32_N_OPERATIONS])
{
    float input[TRS32_N_FEATURES];
    float hidden[75];
    float output[TRS32_N_OUTPUTS];

    /* Extract and normalize features */
    input[0] = ((float)((
                        (((double)(long long)((
                                ((double)(f->count)) > 0.0
                                        ? log2((double)(f->count))
                                        : 0.0))))
                                        < ((double)(20))
                                ? (((double)(long long)((
                                          ((double)(f->count)) > 0.0
                                                  ? log2((double)(f->count))
                                                  : 0.0))))
                                : ((double)(20))))
                - TRS32_norm_mean[0])
            / TRS32_norm_std[0];
    input[1] = ((float)(f->zero_ratio_fp) - TRS32_norm_mean[1])
            / TRS32_norm_std[1];
    input[2] = ((float)((f->mean_abs_delta_u_fp > 5000000000000000000ULL))
                - TRS32_norm_mean[2])
            / TRS32_norm_std[2];
    input[3] =
            ((float)((f->count > 42)) - TRS32_norm_mean[3]) / TRS32_norm_std[3];
    input[4] = ((float)(f->delta_up_ratio_fp) - TRS32_norm_mean[4])
            / TRS32_norm_std[4];
    input[5] = ((float)(f->delta_down_ratio_fp) - TRS32_norm_mean[5])
            / TRS32_norm_std[5];
    input[6] = ((float)((
                        (double)(4294967296ULL)
                        - (double)(f->delta_down_ratio_fp)))
                - TRS32_norm_mean[6])
            / TRS32_norm_std[6];
    input[7]  = ((float)(f->range_u) - TRS32_norm_mean[7]) / TRS32_norm_std[7];
    input[8]  = ((float)(f->range_s) - TRS32_norm_mean[8]) / TRS32_norm_std[8];
    input[9]  = ((float)(f->min_u) - TRS32_norm_mean[9]) / TRS32_norm_std[9];
    input[10] = ((float)((f->min_u == 0)) - TRS32_norm_mean[10])
            / TRS32_norm_std[10];
    input[11] = ((float)(((f->min_u == 0) && (f->max_u > 65535)))
                 - TRS32_norm_mean[11])
            / TRS32_norm_std[11];
    input[12] =
            ((float)((
                     ((double)(f->cardinality_est) * (double)(4294967296ULL))
                     / (((double)(f->count)) > ((double)(1))
                                ? ((double)(f->count))
                                : ((double)(1)))))
             - TRS32_norm_mean[12])
            / TRS32_norm_std[12];
    input[13] = ((float)((
                         ((double)(f->pair_cardinality_est)
                          * (double)(4294967296ULL))
                         / ((((double)(f->count) - (double)(1))) > ((double)(1))
                                    ? (((double)(f->count) - (double)(1)))
                                    : ((double)(1)))))
                 - TRS32_norm_mean[13])
            / TRS32_norm_std[13];
    input[14] = ((float)(f->sorted_gap_cv_fp) - TRS32_norm_mean[14])
            / TRS32_norm_std[14];
    input[15] =
            ((float)(f->min_lb0) - TRS32_norm_mean[15]) / TRS32_norm_std[15];
    input[16] = ((float)(((double)(f->delta_max_s) - (double)(f->delta_min_s)))
                 - TRS32_norm_mean[16])
            / TRS32_norm_std[16];
    input[17] =
            ((float)((
                     (((((double)(f->cardinality_est) + (double)(1))) > 0.0
                               ? log(((double)(f->cardinality_est)
                                      + (double)(1)))
                               : 0.0)
                      - ((((((double)(f->delta_max_s)) > ((double)(0))
                                    ? ((double)(f->delta_max_s))
                                    : ((double)(0)))
                           + (double)(1)))
                                         > 0.0
                                 ? log(((((double)(f->delta_max_s))
                                                         > ((double)(0))
                                                 ? ((double)(f->delta_max_s))
                                                 : ((double)(0)))
                                        + (double)(1)))
                                 : 0.0))
                     - (0.5
                        * (((((double)(f->mean_abs_delta_u_fp)
                              / (double)(4294967296ULL))
                             + (double)(1)))
                                           > 0.0
                                   ? log((((double)(f->mean_abs_delta_u_fp)
                                           / (double)(4294967296ULL))
                                          + (double)(1)))
                                   : 0.0))))
             - TRS32_norm_mean[17])
            / TRS32_norm_std[17];
    input[18] =
            ((float)((
                     ((((double)(f->pair_cardinality_est) + (double)(1))) > 0.0
                              ? log(((double)(f->pair_cardinality_est)
                                     + (double)(1)))
                              : 0.0)
                     - ((((double)(f->cardinality_est) + (double)(1))) > 0.0
                                ? log(((double)(f->cardinality_est)
                                       + (double)(1)))
                                : 0.0)))
             - TRS32_norm_mean[18])
            / TRS32_norm_std[18];
    input[19] =
            ((float)((
                     ((((((((double)(f->pair_cardinality_est) + (double)(1)))
                                          > 0.0
                                  ? log(((double)(f->pair_cardinality_est)
                                         + (double)(1)))
                                  : 0.0)
                         - (0.65
                            * ((((double)(f->cardinality_est) + (double)(1)))
                                               > 0.0
                                       ? log(((double)(f->cardinality_est)
                                              + (double)(1)))
                                       : 0.0)))
                        - 2.0)
                       / 0.4)) < ((double)(0))
                             ? ((double)(0))
                             : (((((((((double)(f->pair_cardinality_est)
                                       + (double)(1)))
                                                     > 0.0
                                             ? log(((double)(f->pair_cardinality_est)
                                                    + (double)(1)))
                                             : 0.0)
                                    - (0.65
                                       * ((((double)(f->cardinality_est)
                                            + (double)(1)))
                                                          > 0.0
                                                  ? log(((double)(f->cardinality_est)
                                                         + (double)(1)))
                                                  : 0.0)))
                                   - 2.0)
                                  / 0.4)) > ((double)(1))
                                        ? ((double)(1))
                                        : ((((((((double)(f->pair_cardinality_est)
                                                 + (double)(1)))
                                                               > 0.0
                                                       ? log(((double)(f->pair_cardinality_est)
                                                              + (double)(1)))
                                                       : 0.0)
                                              - (0.65
                                                 * ((((double)(f->cardinality_est)
                                                      + (double)(1)))
                                                                    > 0.0
                                                            ? log(((double)(f->cardinality_est)
                                                                   + (double)(1)))
                                                            : 0.0)))
                                             - 2.0)
                                            / 0.4)))))
             - TRS32_norm_mean[19])
            / TRS32_norm_std[19];

    /* Layer 1 */
    for (int j = 0; j < 75; j++) {
        float sum = TRS32_b1[j];
        for (int i = 0; i < 20; i++) {
            sum += input[i] * TRS32_w1[i][j];
        }
        hidden[j] = TRS32_relu(sum);
    }

    /* Layer 2 */
    for (int j = 0; j < 11; j++) {
        float sum = TRS32_b2[j];
        for (int i = 0; i < 75; i++) {
            sum += hidden[i] * TRS32_w2[i][j];
        }
        if (logits_out)
            logits_out[j] = sum;
        output[j] = TRS32_sigmoid(sum);
    }

    /* Copy scores and find best */
    int best = 0;
    for (int j = 0; j < TRS32_N_OUTPUTS; j++) {
        if (scores_out) {
            scores_out[j] = output[j];
        }
        if (output[j] > output[best])
            best = j;
    }

    return best;
}

int TRS_score_num32_operations(
        const TRS_NumericFeatures* f,
        float scores_out[TRS_SCORE_NUM32_N_OPERATIONS])
{
    return TRS_score_num32_operations_with_logits(f, scores_out, NULL);
}

